tests.executable:
from httpbin.core import app
client = app.test_client()

def test_get_cookies_top_level_key_is_exactly_cookies_not_other():
    r = client.get('/cookies', headers={'Cookie': 'token=xyz'})
    assert r.status_code == 200
    data = r.get_json()
    assert set(data.keys()) == {'cookies'}
    assert data['cookies'] == {'token': 'xyz'}

test_get_cookies_top_level_key_is_exactly_cookies_not_other()
